<?php

declare(strict_types=1);
require_once __DIR__ . '/authorization.php';require_once __DIR__ . '/csrf.php';requireCustomer();verifyCsrf();
$id=(int)($_POST['booking_id']??0);$userId=(int)$_SESSION['user_id'];
$stmt=$conn->prepare("SELECT id,status,booking_date,payment_status FROM bookings WHERE id=? AND user_id=? FOR UPDATE");
try{$conn->begin_transaction();$stmt->bind_param('ii',$id,$userId);$stmt->execute();$b=$stmt->get_result()->fetch_assoc();if(!$b||!in_array($b['status'],['Pending','Approved'],true)||$b['booking_date']<date('Y-m-d')){$conn->rollback();redirectTo('booking-history.php?error='.urlencode('This booking cannot be cancelled.'));}if($b['payment_status']==='Paid'){$conn->rollback();redirectTo('booking-history.php?error='.urlencode('A paid booking must be cancelled by salon staff so refund handling can be confirmed.'));}$u=$conn->prepare("UPDATE bookings SET status='Cancelled' WHERE id=?");$u->bind_param('i',$id);$u->execute();$d=$conn->prepare('DELETE FROM booking_slots WHERE booking_id=?');$d->bind_param('i',$id);$d->execute();$p=$conn->prepare("UPDATE payments SET status=CASE WHEN status IN ('Pending Verification','Pending Online Payment') THEN 'Cancelled' ELSE status END WHERE booking_id=?");$p->bind_param('i',$id);$p->execute();$conn->query("UPDATE bookings SET payment_status=CASE WHEN payment_status IN ('Pending Verification','Pending Online Payment') THEN 'Cancelled' ELSE payment_status END WHERE id=".(int)$id);audit($conn,'booking_cancelled','booking',$id);$conn->commit();redirectTo('booking-history.php?cancelled=1');}catch(Throwable $e){$conn->rollback();redirectTo('booking-history.php?error='.urlencode('Cancellation failed.'));}
